-- One-time setup. Run after 01_daily_raw.sql and 02_ingest_access.sql.
-- This is a public key. The matching private key stays in .secrets/.
USE ROLE SECURITYADMIN;

CREATE USER NORTHBRIDGE_LOADER
    TYPE = SERVICE
    RSA_PUBLIC_KEY = ''
    DEFAULT_ROLE = NORTHBRIDGE_INGEST_DEV
    DEFAULT_WAREHOUSE = COMPUTE_WH
    DEFAULT_NAMESPACE = NORTHBRIDGE_DEV.RAW;

GRANT ROLE NORTHBRIDGE_INGEST_DEV TO USER NORTHBRIDGE_LOADER;
DESCRIBE USER NORTHBRIDGE_LOADER;
